fn dispatch_input(d: &mut Dispatch<'_>) -> bool {
    // 借用别名:下面整段是从 `run()` 原样搬来的,保留裸名最好读。
    let (ctl, m, profile, held) = (d.ctl, d.m, d.profile, d.held);
    let (ev, fresh_press, fps_running, fps_active, aim_down) =
        (d.ev, d.fresh_press, d.fps_running, d.fps_active, d.aim_down);
    let zoom_sep = &mut *d.zoom_sep;
    let (fps_fingers, combo_fingers, macro_down) = (d.fps_fingers, d.combo_fingers, d.macro_down);
    let wheels = &mut *d.wheels;
    // 这几个在下面按 `&mut name` 传参,绑定本身得是 `mut`(二次再借用)
    let mut fingers = &mut *d.fingers;
    let mut macro_exec_seq = &mut *d.macro_exec_seq;
    let mut scheduled = &mut *d.scheduled;
    let mut live = &mut *d.live;
    let mut active_android_keys = &mut *d.active_android_keys;
    let last_refuse_note = &mut *d.last_refuse_note;
    let pending_notice = &mut *d.pending_notice;
    let aim_st = &mut *d.aim_st;

    // ---- 临时轮盘启用键 ----
    let mut consumed = false;
    for (j, w) in profile.wheels.iter().enumerate() {
        let Some(t) = &w.temp else { continue };
        // 组合键启用键(用户 2026-10-10 第 2 条):事件只要**是集合成员**就归轮盘
        // 处理(消费事件),集合是否整个按着由下面的 `want_active` 判断 ——
        // 与 `aim.hold_key` 的门控写法同构(成员事件到来时重算整集合状态)。
        // 不能在这里就要求"整个集合按着":松开最后一个成员的那一帧 `held` 已经
        // 不含该键,断言会把**抬起**事件放走,启用键的抬起就不再被消费,停用也
        // 不再当场发生(旧单键时代这条是一直被消费的)。
        if !t.key.contains(&ev.code) {
            continue;
        }
        // 目标状态:长按模式 = 按住期间生效;切换模式 = **只在按下的那一瞬间**翻转
        // (同样只认上升沿:否则按住切换键不放,自动重复会把它来回翻转)
        let want_active = match t.mode {
            // 组合键:整个集合此刻都按着才算启用;任一成员抬起就立刻停用。
            // 滚轮键(用户 2026-10-10 第 2 条):一齿的"抬起"不代表松手 ——
            // 长按型临时轮盘跟着轮齿闩锁一起保持启用,真正的停用由定期维护里
            // `rederive_hold_temp_wheels` + `reconcile_wheels` 收尾。
            TempMode::Hold => {
                key_set_down(&t.key, held) || (is_wheel_code(ev.code) && held.has(ev.code))
            }
            TempMode::Toggle => {
                if fresh_press {
                    !wheels[j].active
                } else {
                    wheels[j].active
                }
            }
        };
        if want_active != wheels[j].active {
            if want_active {
                wheels[j].active = true;
                // 启用瞬间,释放与方向键冲突的普通绑定(避免触点卡死),
                // 再按物理状态对账:已经按着的方向键立刻推动摇杆(不必松手重按),
                // 该让位的普通绑定也一定被抬起来
                release_conflicting_binds(
                    ctl,
                    &m,
                    profile,
                    &mut fingers,
                    &mut active_android_keys,
                    w,
                );
            } else {
                deactivate_wheel(ctl, &m, j, w, &mut wheels[j]);
            }
            // 归属刚改变 -> 两个方向都立刻对账一遍。
            // 停用这一边正是"松开启用键后,原来长按着的键必须继续奏效"的关键:
            // 那个键还按在手上,普通绑定必须马上补上它的触点。
            let extra =
                fps_fingers.count + combo_fingers.count + macro_down.len() + usize::from(aim_down);
            reconcile_binds(
                ctl,
                &m,
                profile,
                wheels,
                fps_active,
                extra,
                &held,
                &mut fingers,
                &mut active_android_keys,
                &mut live,
            );
            reconcile_wheels(
                ctl,
                &m,
                profile,
                wheels,
                &held,
                fingers.count
                    + fps_fingers.count
                    + combo_fingers.count
                    + macro_down.len()
                    + usize::from(aim_down),
                &mut live,
            );
        }
        consumed = true;
    }
    if consumed {
        return true;
    }

    // ---- 轮盘方向键(仅生效中的轮盘:永久 或 已启用的临时) ----
    // 方向状态 = "该轮盘此刻是否生效 × 对应物理键是否按着"(见 reconcile_wheels),
    // 所以这里只判断"这个事件是不是某个生效轮盘的方向键",剩下的交给对账。
    // 多个**永久**轮盘共用同一个方向键时,它们会一起响应(与旧行为一致);
    // 但**已启用的临时轮盘**对永久轮盘有抢占优先级(R1,2026-10-08):
    // 该键位上只有临时轮盘响应,永久轮盘让位。
    let mut handled = false;
    let mut execute_wheel: Option<usize> = None;
    // 本键是否已被"已启用的临时轮盘"占走:只算一次,循环里直接判(R1)。
    let temp_taken = key_taken_by_active_temp_wheel(profile, wheels, ev.code);
    for (j, w) in profile.wheels.iter().enumerate() {
        let engaged = w.temp.is_none() || wheels[j].active;
        if !engaged
            || (w.temp.is_none() && temp_taken)
            || !w
                .active_dirs()
                .iter()
                .any(|(_, key)| key.contains(&ev.code))

