/// 把一次「按键/组合键」捕获落到正确的宏缓冲上。
///
/// 三处宏步骤编辑器里有两处（可视化键位页展开、宏页「已录宏」展开）编辑的是
/// `binds[i]` 的**每帧克隆副本**，改动只有写回 `Shared` 才算数；而宏页编辑区
/// 编辑的是 `self.macro_page_instructions`。捕获发生在**下一帧的事件阶段**，
/// 那时副本早已不在 —— 所以捕获必须记住"这一次在给谁改"（[`MacroKeyTarget`]）。
fn write_macro_keys(&mut self, target: MacroKeyTarget, index: usize, keys: &[u16], slot: usize) {
    match target {
        MacroKeyTarget::Page => {
            if let Some(MacroInstruction::Combo { keys: dst, .. }) =
                self.macro_page_instructions.get_mut(index)
            {
                for (i, k) in keys.iter().enumerate() {
                    let at = slot + i;
                    if at < dst.len() { dst[at] = *k; } else if at < 4 { dst.push(*k); }
                }
            }
        }
        MacroKeyTarget::Bind(bind) => {
            let mut g = lock_shared(&self.shared);
            if let Some(b) = g.profile.binds.get_mut(bind) {
                if let Action::Macro(m) = &mut b.action {
                    if let Some(MacroInstruction::Combo { keys: dst, .. }) = m.instructions.get_mut(index) {
                        for (i, k) in keys.iter().enumerate() {
                            let at = slot + i;
                            if at < dst.len() { dst[at] = *k; } else if at < 4 { dst.push(*k); }
                        }
                    }
                }
            }
        }
    }
}
```
