/// 超出现有长度时按 [`MACRO_COMBO_MAX_KEYS`] 上限扩展。
fn write_combo_keys(dst: &mut Vec<u16>, slot: usize, codes: &[u16]) {
    for (i, code) in codes.iter().enumerate() {
        let at = slot + i;
        if at < dst.len() {
