    // 1200 就这样变成了 1040。基准按 pid 分开之后这个误差不存在了。
    let mut last: std::collections::HashMap<u64, (f32, f32)> = std::collections::HashMap::new();
    let mut st = PathStats::default();
    for ev in &dev.evs {
        let DevEv::Touch {
            action, pid, x, y, ..
        } = *ev
        else {
            continue;
        };
        if !want(pid) {
            continue;
        }
        let p = (x as f32, y as f32);
        match action {
            ACTION_DOWN => {
                st.downs += 1;
                last.insert(pid, p);
            }
            ACTION_MOVE => {
                st.moves += 1;
                if let Some(prev) = last.get(&pid) {
                    let dx = p.0 - prev.0;
                    let dy = p.1 - prev.1;
                    st.net.0 += dx;
                    st.net.1 += dy;
                    st.path += dx.hypot(dy);
                }
                last.insert(pid, p);
            }
            ACTION_UP => {
                st.ups += 1;
                last.remove(&pid);
            }
            _ => {}
        }
    }
    st
