content.text:
Now the selftest rewrite for checks ③-⑤. Let me replace the region from `// ③ 屏幕合成` through the ⑥ `不抢焦点` check with:
- ③ composited white (keep, should now pass)
- ③b layered attributes armed (GetLayeredWindowAttributes)
- ④/⑤ probe matrix: colorkey → center click-through, circle → mask; alpha=1 → ? 
- ⑥ 不抢焦点 (keep)

Let me write the replacement carefully, with the exact old text. The old region (from my file content):

```rust
    // ③ 屏幕合成:蒙版中心(圆内部=未绘制区)应透出**底下的白窗**
    unsafe {
        let screen = GetDC(std::ptr::null_mut());
        let composited = GetPixel(screen, cx, cy);
        ReleaseDC(std::ptr::null_mut(), screen);
        check(
            "合成透明(白底透出来)",
            composited & 0x00FF_FFFF == rgb(255, 255, 255),
            format!("合成像素={composited:#010X} 期望=0x00FFFFFF(白)"),
        );
    }

    // ④ 点击归属:不穿透时 WindowFromPoint 必须是蒙版自己(⇒ 投屏窗口收不到)
    unsafe {
        let pt = POINT { x: cx, y: cy };
        let at = WindowFromPoint(pt);
        check(
            "默认吃掉鼠标(命中蒙版自己)",
            at == hwnd,
            format!("WindowFromPoint={at:p} 蒙版={hwnd:p}"),
        );
        // ⑤ 切成穿透:必须落到底图窗口上
        let mut f2 = Frame::new(rect);
        f2.passthrough = true;
        mask.set_frame(f2);
        thread::sleep(Duration::from_millis(150));
        let at2 = WindowFromPoint(pt);
        check(
            "穿透开关(命中下层窗口)",
            at2 != hwnd,
            format!("WindowFromPoint={at2:p} 蒙版={hwnd:p} 底图={:p}", bg.0),
        );
        // ⑥ 不抢焦点
        let fg = GetForegroundWindow();
        check("不抢焦点", fg != hwnd, format!("前台={fg:p}"));
    }
```

New version:

```rust
    // ③ 屏幕合成:蒙版中心(圆内部=未绘制区)应透出**底下的白窗**
    unsafe {
        let screen = GetDC(std::ptr::null_mut());
        let composited = GetPixel(screen, cx, cy);
        ReleaseDC(std::ptr::null_mut(), screen);
        check(
            "合成透明(白底透出来)",
            composited & 0x00FF_FFFF == rgb(255, 255, 255),
            format!("合成像素={composited:#010X} 期望=0x00FFFFFF(白)"),
        );
    }

    // ④ 分层属性确实挂上了(与"像素看起来对"互为独立证据:即使采样坐标系
    //    有偏移,这一条也照样说明"键色透明"这套机制是武装着的)
    unsafe {
        let mut key: u32 = 0;
        let mut alpha: u8 = 0;
        let mut flags: u32 = 0;
        let ok = GetLayeredWindowAttributes(hwnd, &mut key, &mut alpha, &mut flags);
        check(
            "分层属性已武装(LWA_COLORKEY + 键色)",
            ok != 0 && key == KEY_COLOR && flags & LWA_COLORKEY != 0,
            format!("ok={ok} key={key:#010X} alpha={alpha} flags=0x{flags:X}"),
        );
    }

    // ⑤ 命中归属 —— 本轮探雷**最重要的结论**,单独立一组:
    //    分层窗口的"透明像素"同时也是"点不到的像素",所以"看得见画面"与
    //    "吃掉鼠标"在同一块窗口上**不可兼得**。这里把两种属性各测一遍,
    //    让结论有据可查(而不是靠猜)。
    unsafe {
        let pt = POINT { x: cx, y: cy };
        let on_circle = POINT {
            x: cx - 60,
            y: cy,
        };
        // (a) 键色透明:整片透明 ⇒ 整片点不到
        SetLayeredWindowAttributes(hwnd, KEY_COLOR, 0, LWA_COLORKEY);
        thread::sleep(Duration::from_millis(80));
        let at_center = WindowFromPoint(pt);
        let at_circle = WindowFromPoint(on_circle);
        check(
            "键色透明:未绘制区点不到(落到下层)",
            at_center != hwnd,
            format!("中心 WindowFromPoint={at_center:p} 蒙版={hwnd:p} 底图={:p}", bg.0),
        );
        check(
            "键色透明:绘制区仍归蒙版",
            at_circle == hwnd,
            format!("圈上 WindowFromPoint={at_circle:p} 蒙版={hwnd:p}"),
        );
        // (b) 整体 alpha=1:不透明(肉眼几乎看不出),看还能不能吃到点击
        SetLayeredWindowAttributes(hwnd, 0, 1, LWA_ALPHA);
        thread::sleep(Duration::from_millis(80));
        let at_alpha = WindowFromPoint(pt);
        check(
            "整体 alpha=1:整片归蒙版(可作"隔膜窗")",
            at_alpha == hwnd,
            format!("中心 WindowFromPoint={at_alpha:p} 蒙版={hwnd:p}"),
        );
        // 复原成生产形态(键色透明)
        SetLayeredWindowAttributes(hwnd, KEY_COLOR, 0, LWA_COLORKEY);
        thread::sleep(Duration::from_millis(80));
        // ⑥ 不抢焦点
        let fg = GetForegroundWindow();
        check("不抢焦点", fg != hwnd, format!("前台={fg:p}"));
    }
```

Careful with format strings containing quotes: `"整体 alpha=1:整片归蒙版(可作"隔膜窗")"` — Rust string with inner double quotes → must escape: use 「」 instead. Let me use 「隔膜窗」.

Also `flags & LWA_COLORKEY` — flags is u32, LWA_COLORKEY is u32-ish ✓.

`GetLayeredWindowAttributes(hwnd, &mut key, &mut alpha, &mut flags)` — signature expects `*mut COLORREF` (u32), `*mut u8`, `*mut LAYERED_WINDOW_ATTRIBUTES_FLAGS` (u32). `&mut key` where key: u32 ✓, `&mut flags` u32 ✓.

