pub fn mouse_shield_swallows(shield_on: bool, msg: u32, swallow: u16) -> bool {
    if !shield_on || !MOUSE_HOOK_MSG_CODES.contains(&msg) {
        return false;
    }
    match mouse_button_bits(msg) {
        Some(bits) => swallow & bits != 0,
        None => true,
