        // **绑定才吞、没绑定放行** —— 正是用户 2026-10-11 第 4 条要的语义。
        272 => Some(1 << 10),
        1 => Some(1 << 0),   // KEY_ESC
        87 => Some(1 << 1),  // KEY_F11(全屏)
        273 => Some(1 << 2), // BTN_RIGHT(右键菜单)

