import json,collections
L=[json.loads(l) for l in open('D:/trace3.jsonl',encoding='utf-8') if l.strip()]
buck=collections.defaultdict(lambda:{'m':0,'mv':0,'t':0,'dx':0.0,'pids':collections.Counter()})
last={}
for d in L:
    s=d['t']//1000; b=buck[s]
    if d.get('k')=='in' and d.get('e')=='motion':
        b['m']+=1; b['mv']+=abs(d['dx'])+abs(d['dy'])
    if d.get('k')=='out' and d.get('e')=='touch':
        pid=d['pid']
        if pid in (3000,3001):
            b['pids'][pid]+=1
            if d['a']==2:
                if pid in last: b['dx']+=abs(d['x']-last[pid])
                b['t']+=1
            last[pid]=(d['x'],d['y'])
        if d['a']==1: last.pop(pid,None)
print("秒 | 鼠标事件 位移量 | 瞄准MOVE 设备位移px | 落指")
bad=[]
for s in sorted(buck):
    b=buck[s]
    if b['m']>=8 and b['t']==0: bad.append(s)
    if s%5==0 or (b['m']>=8 and b['t']==0):
        print(f"{s:3d} | {b['m']:4d} {b['mv']:7.0f} | {b['t']:4d} {b['dx']:7.0f} | {sum(b['pids'].values())}")
print("\n**鼠标在动但瞄准一条 MOVE 都没有的秒**:", bad if bad else "无")
tot_m=sum(b['m'] for b in buck.values()); tot_t=sum(b['t'] for b in buck.values())
print("总计: 鼠标事件",tot_m,"瞄准MOVE",tot_t)
