{"command": "python - <<'PY'
import json,collections
L=[json.loads(l) for l in open('D:/trace3.jsonl',encoding='utf-8') if l.strip()]
openp={}   # pid -> 最近动作
ev=[]
for d in L:
    if d.get('k')!='out' or d.get('e')!='touch': continue
    pid,a=d['pid'],d['a']
    if a==0: openp[pid]=True
    elif a==1: openp.pop(pid,None)
    ev.append((d['t'],pid,a,len(openp)))
def open_at(t):
    o=set()
    for tt,pid,a,_ in ev:
        if tt>t: break
        if a==0: o.add(pid)
        elif a==1: o.discard(pid)
    return o
for a,b in [(76000,82100),(60000,61500),(29000,31000),(1000,10000)]:
    o=open_at(a)
    print(f"t={a}: 开着的注入触点 {len(o)} 个 {sorted(o)}")
# 瞄准 pid 的最后动作
for pid in (3000,3001):
    acts=[(t,a) for t,p,a,_ in ev if p==pid]
    print(f"\npid={pid} 动作数 {len(acts)};最后 8 条:",acts[-8:])
# 全片各 pid 的 DOWN/UP 平衡
bal=collections.Counter()
for t,p,a,_ in ev:
    if a==0: bal[p]+=1
    elif a==1: bal[p]-=1
print("\n各 pid DOWN-UP 差(非 0 = 泄漏/未抬起):",{k:v for k,v in bal.items() if v!=0})
print("注入触点 pid 清单:",sorted({p for _,p,_,_ in ev}))
