const AIM_RESUME_GAP: Duration = Duration::from_millis(400);

fn aim_flush(ctl: &ControlClient, m: &Mapper, aim: &Aim, st: &mut AimState, at: Instant) {
    let dead = aim.drag_deadzone.clamp(0.0, 400.0);
