    /// 才恢复。看不到物理触摸,就用"停了半秒又动"这个伴随信号续接一次。
    #[test]
    fn scenario_aim_resumes_with_a_fresh_down_after_a_pause() {
        let screen = (1280u32, 2772u32);
        let h = Harness::start(fps_profile(screen), screen);
        h.tap(67); // F9 进 FPS
        h.settle(60);
        // 极小的位移:留下几像素偏移但**不足以触发静止归中**(门槛 14px),
        // 这样"停顿后多出一次 DOWN"只可能来自续接逻辑本身。
        h.feed_motion(3.0, 0.0);
        h.settle(80);
        let before = path_stats(&h.device(), |_| true).downs;
        h.settle(600); // 停 600ms > AIM_RESUME_GAP(400ms)
        h.feed_motion(3.0, 0.0);
        h.settle(150);
        let after = path_stats(&h.device(), |_| true).downs;
        assert!(
            after > before,
            "停顿之后的第一下位移必须重新落指:down {before} → {after}"
        );
        assert_clean(&h.stop(), "停顿时续接");
    }
