{"content": "// 只读探测:F5 键盘钩子探针误判的根因实验。
// 形态与生产代码逐字相同:WH_KEYBOARD_LL + SendInput(VK 0xFF, dwExtraInfo=PROBE_MAGIC)。
// 零依赖(手写 FFI),不影响任何配置,不发任何有功能的按键。
#![allow(non_snake_case, non_camel_case_types)]

use std::sync::atomic::{AtomicU64, Ordering};

type HHOOK = *mut core::ffi::c_void;
type HWND = *mut core::ffi::c_void;
type HINSTANCE = *mut core::ffi::c_void;
type WPARAM = usize;
type LPARAM = isize;
type LRESULT = isize;

const WH_KEYBOARD_LL: i32 = 13;
const HC_ACTION: i32 = 0;
const WM_KEYDOWN: u32 = 0x0100;
const WM_KEYUP: u32 = 0x0101;
const WM_SYSKEYDOWN: u32 = 0x0104;
const WM_SYSKEYUP: u32 = 0x0105;
const INPUT_KEYBOARD: u32 = 1;
const KEYEVENTF_KEYUP: u32 = 0x0002;
const PROBE_VK: u16 = 0xFF;
const PROBE_MAGIC: usize = 0x5343_5041_4431; // "SCPAD1"

#[repr(C)]
struct KBDLLHOOKSTRUCT {
    vkCode: u32,
    scanCode: u32,
    flags: u32,
    time: u32,
    dwExtraInfo: usize,
}

#[repr(C)]
struct KEYBDINPUT {
    wVk: u16,
    wScan: u16,
    dwFlags: u32,
    time: u32,
    dwExtraInfo: usize,
}

#[repr(C)]
union INPUT_0 {
    ki: std::mem::ManuallyDrop<KEYBDINPUT>,
    _pad: [u64; 4],
}

#[repr(C)]
struct INPUT {
    r#type: u32,
    Anonymous: INPUT_0,
}

#[link(name = "user32")]
unsafe extern "system" {
    fn SetWindowsHookExW(idHook: i32, lpfn: Option<unsafe extern "system" fn(i32, WPARAM, LPARAM) -> LRESULT>, hmod: HINSTANCE, dwThreadId: u32) -> HHOOK;
    fn CallNextHookEx(hhk: HHOOK, nCode: i32, wParam: WPARAM, lParam: LPARAM) -> LRESULT;
    fn UnhookWindowsHookEx(hhk: HHOOK) -> i32;
    fn GetMessageW(lpMsg: *mut MSG, hWnd: HWND, wMsgFilterMin: u32, wMsgFilterMax: u32) -> i32;
    fn TranslateMessage(lpMsg: *const MSG) -> i32;
    fn DispatchMessageW(lpMsg: *const MSG) -> LRESULT;
    fn PostThreadMessageW(idThread: u32, Msg: u32, wParam: WPARAM, lParam: LPARAM) -> i32;
    fn GetCurrentThreadId() -> u32;
    fn SendInput(cInputs: u32, pInputs: *const INPUT, cbSize: i32) -> u32;
    fn GetLastError() -> u32;
}

#[repr(C)]
struct MSG {
    hwnd: HWND,
    message: u32,
    wParam: WPARAM,
    lParam: LPARAM,
    time: u32,
    pt_x: i32,
    pt_y: i32,
}

const WM_APP_HB: u32 = 0x8000 + 1;

static SEEN: AtomicU64 = AtomicU64::new(0);
static SEEN_NO_MAGIC: AtomicU64 = AtomicU64::new(0);
static SEEN_NO_INJECTED: AtomicU64 = AtomicU64::new(0);
static SEEN_VK_OTHER: AtomicU64 = AtomicU64::new(0);
static CALLBACK_TOTAL: AtomicU64 = AtomicU64::new(0);

unsafe extern "system" fn keyboard_proc(code: i32, wparam: WPARAM, lparam: LPARAM) -> LRESULT {
    CALLBACK_TOTAL.fetch_add(1, Ordering::Relaxed);
    if code == HC_ACTION {
        let kb = unsafe { &*(lparam as *const KBDLLHOOKSTRUCT) };
        if kb.vkCode as u16 == PROBE_VK {
            // 逐条记录"为什么没认出来",而不是只记认出来的
            if kb.dwExtraInfo != PROBE_MAGIC {
                SEEN_NO_MAGIC.fetch_add(1, Ordering::Relaxed);
            } else if kb.flags & 0x10 == 0 {
                // LLKHF_INJECTED = 0x10
                SEEN_NO_INJECTED.fetch_add(1, Ordering::Relaxed);
            } else {
                SEEN.fetch_add(1, Ordering::Relaxed);
            }
        } else if matches!(wparam as u32, WM_KEYDOWN | WM_KEYUP | WM_SYSKEYDOWN | WM_SYSKEYUP) {
            SEEN_VK_OTHER.fetch_add(1, Ordering::Relaxed);
        }
    }
    unsafe { CallNextHookEx(std::ptr::null_mut(), code, wparam, lparam) }
}

fn main() {
    unsafe {
        let hook = SetWindowsHookExW(WH_KEYBOARD_LL, Some(keyboard_proc), std::ptr::null_mut(), 0);
        if hook.is_null() {
            println!("RESULT=HOOK_INSTALL_FAILED err={}", GetLastError());
            return;
        }
        println!("HOOK_INSTALLED ok");

        let tid = GetCurrentThreadId();

        // 与生产相同的节拍:1 秒一枚探针,共 4 枚
        std::thread::spawn(move || {
            for i in 1..=4u32 {
                std::thread::sleep(std::time::Duration::from_millis(1000));
                let mk = |flags: u32| INPUT {
                    r#type: INPUT_KEYBOARD,
                    Anonymous: INPUT_0 {
                        ki: std::mem::ManuallyDrop::new(KEYBDINPUT {
                            wVk: PROBE_VK,
                            wScan: 0,
                            dwFlags: flags,
                            time: 0,
                            dwExtraInfo: PROBE_MAGIC,
                        }),
                    },
                };
                let ins = [mk(0), mk(KEYEVENTF_KEYUP)];
                let sent = SendInput(ins.len() as u32, ins.as_ptr(), std::mem::size_of::<INPUT>() as i32);
                println!(
                    "PROBE #{i}: SendInput returned {sent}/{} (last_err={})",
                    ins.len(),
                    GetLastError()
                );
                // 让钩子线程处理消息(生产里是 WM_APP_HB,这里直接投一个)
                let _ = PostThreadMessageW(tid, WM_APP_HB, 0, 0);
            }
            std::thread::sleep(std::time::Duration::from_millis(500));
            let _ = PostThreadMessageW(tid, WM_APP_HB + 1, 0, 0); // 结束
        });

        let mut msg: MSG = std::mem::zeroed();
        loop {
            let r = GetMessageW(&mut msg, std::ptr::null_mut(), 0, 0);
            if r <= 0 {
                break;
            }
            if msg.message == WM_APP_HB + 1 {
                break;
            }
            TranslateMessage(&msg);
            DispatchMessageW(&msg);
        }

        UnhookWindowsHookEx(hook);
        println!("--- 结果 ---");
        println!("回调总次数           = {}", CALLBACK_TOTAL.load(Ordering::Relaxed));
        println!("认出的探针(全条件满足) = {}", SEEN.load(Ordering::Relaxed));
        println!("VK=FF 但魔数不符       = {}", SEEN_NO_MAGIC.load(Ordering::Relaxed));
        println!("VK=FF 但无 INJECTED    = {}", SEEN_NO_INJECTED.load(Ordering::Relaxed));
        println!("其它 VK 的按键事件      = {}", SEEN_VK_OTHER.load(Ordering::Relaxed));
    }
}
