static SEQ: AtomicU64 = AtomicU64::new(0);
static SEQ_OF_SEEN: AtomicU64 = AtomicU64::new(0);   // 回调写入 seen 时的序号
static SEQ_OF_SENT: AtomicU64 = AtomicU64::new(0);   // 写 sent 时的序号
static SEEN_COUNT: AtomicU64 = AtomicU64::new(0);
static SENT_COUNT: AtomicU64 = AtomicU64::new(0);
// 生产语义的两个"时间戳"
