                    SENT_COUNT.fetch_add(1, Ordering::Relaxed);
                }
                // 生产语义:probe_missed(sent, seen) = sent != 0 && seen < sent
                let sent = PROBE_SENT_MS.load(Ordering::SeqCst);
                let seen = PROBE_SEEN_MS.load(Ordering::SeqCst);
                let missed = sent != 0 && seen < sent;
                if missed { MISSES.fetch_add(1, Ordering::Relaxed); }
                println!(
