        let sent = SENT_COUNT.load(Ordering::Relaxed);
        let seq_seen = SEQ_OF_SEEN.load(Ordering::SeqCst);
        let seq_sent = SEQ_OF_SENT.load(Ordering::SeqCst);
        println!("--- 结果 ---");
        println!("发出探针 {sent} 枚;钩子认出 {seen} 个按键事件");
        println!("最后一次回调序号 = {seq_seen};最后一次写 sent 序号 = {seq_sent}");
        println!("累计被判 miss 的拍数 = {}", MISSES.load(Ordering::Relaxed));
        println!("--- 结论 ---");
        if seen > 0 && seq_seen < seq_sent {
            println!("ROOT_CAUSE=钩子在 SendInput 期间被重入回调 ⇒ seen 序号早于 sent ⇒ seen<sent 恒真 ⇒ 永远误判无回音");
        } else if seen > 0 && seq_seen > seq_sent {
            println!("ORDER_OK=回调晚于写 sent(本机不是这个原因)");
        } else {
            println!("SEEN=0(回调没看到探针)");
        }
    }
}
