struct KEYBDINPUT { wVk: u16, wScan: u16, dwFlags: u32, time: u32, dwExtraInfo: usize }
#[repr(C)]
union INPUT_0 { ki: std::mem::ManuallyDrop<KEYBDINPUT>, _pad: [u64; 4] }
#[repr(C)]
struct INPUT { r#type: u32, Anonymous: INPUT_0 }
#[repr(C)]
struct MSG { hwnd: HWND, message: u32, wParam: WPARAM, lParam: LPARAM, time: u32, pt_x: i32, pt_y: i32 }

