                if missed { MISSES.fetch_add(1, Ordering::Relaxed); }
                println!(
                    "  拍: sent_seq={sent} seen_seq={seen} → probe_missed={missed}  (累计 miss={})",
                    MISSES.load(Ordering::Relaxed)
