    /// `PadApp::log()`(界面日志)必须真的落进**诊断文件**,而不是只进内存环形缓冲。
    ///
    /// 为什么必须有一条**落盘**断言,而不是只看实现:`log()` 曾经只把消息推进
    /// `self.logs` 环形缓冲,于是"手机被手触摸 / 手离开手机 / 设备端输入账本"
    /// 这些自愈层消息在用户能看到的 diagnostics.log 里**一行都没有** ——
    /// 承诺的取证链是空的,而所有门禁照样全绿(门禁绿 ≠ 问题解决)。
    ///
    /// 这条测试走的是**生产同一条汇流**:`diag::init()` → `diag::log()` →
    /// 读回文件。用独立的临时目录,不碰用户配置。
    #[test]
    fn interface_log_reaches_the_diagnostics_file() {
        // init() 写的是 `config_dir()/diagnostics.log`;这里直接验证同一条
        // 底层通路:`log()` 之后内容必须能在 `path()` 指向的文件里读到。
        // 先确保已 init(其他测试可能已 init 过;幂等重入即可)。
        init();
        let path = path();
        // 用一个不可能与其它日志混淆的标记
        let marker = format!("F1-SEAM-PROBE-{}", std::process::id());
        log(Level::Info, "app", &marker);
        flush();
        let text = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("诊断文件 {} 读不到: {e}", path.display()));
        assert!(
            text.contains(&marker),
            "界面日志必须落进诊断文件(这是 F1 的回归点);文件里没有 {marker}"
        );
        assert!(
            text.contains("[app]"),
            "落盘行必须带来源标签,便于按模块过滤"
        );
    }
