    ///
    /// 这里只验证"没有在途监听时调用是安全的" —— 真正的 kill 语义需要真进程,
    /// 由真机只读验证覆盖(退出后 `ps -A | grep getevent` 为空)。
    #[test]
    fn stopping_touch_watches_is_idempotent() {
        stop_physical_touch_watches();
        stop_physical_touch_watches();
        // 没有 pid 时 pid 表应保持为空,不会 panic、也不会留下悬挂项
        assert!(
            TOUCH_WATCH_PIDS.lock().map(|v| v.is_empty()).unwrap_or(true),
            "无在途监听时 pid 表必须为空"
        );
    }

    /// ⑤ `getevent -pl` fixture:只有带 `ABS_MT_TRACKING_ID` 的节点才是触摸屏,", "old_string": "    /// ⑤ `getevent -pl` fixture:只有带 `ABS_MT_TRACKING_ID` 的节点才是触摸屏,"}

