{"file_path": "D:\GitHub\scrcpy-pad-developing-yaml\src\app.rs", "new_string": "    /// **宏录制热键**(用户 2026-10-12 任务书):六条验收标准逐条钉住。
    ///
    /// 判定是纯函数(`macro_hotkey_action`),所以这里能直接覆盖任务书里
    /// "未勾选启用不触发""只启用其一""都不启用行为不变"这些条款,
    /// 不必起界面。
    #[test]
    fn macro_record_hotkeys_follow_the_spec() {
        const K1: u16 = 88; // 随便两个不冲突的键码
        const K2: u16 = 89;
        const OTHER: u16 = 90;

        // ① 只启用开始键并绑定 K1:按 K1 ⇒ Start(进入等待首个按键,不立即录制)
        assert_eq!(
            PadApp::macro_hotkey_action(K1, K1, true, 0, false, false),
            MacroHotkey::Start,
            "启用+绑定 ⇒ 按 K1 进入等待状态"
        );
        // ② 未勾选启用 ⇒ 即使绑了键也不触发任何行为
        assert_eq!(
            PadApp::macro_hotkey_action(K1, K1, false, 0, false, false),
            MacroHotkey::None,
            "未勾选启用:绑了也不触发"
        );
        assert_eq!(
            PadApp::macro_hotkey_action(K2, 0, false, K2, false, true),
            MacroHotkey::None,
            "终止键未启用:录制中按它也不触发"
        );
        // ③ 未绑定(键码 0)⇒ 不触发(不能因为 0==0 就误判)
        assert_eq!(
            PadApp::macro_hotkey_action(0, 0, true, 0, true, false),
            MacroHotkey::None,
            "未绑定时按键码 0 不得与任何键匹配"
        );
        // ④ 启用终止键并绑定 K2:录制中按 K2 ⇒ Stop;非录制状态 ⇒ 无操作
        assert_eq!(
            PadApp::macro_hotkey_action(K2, 0, false, K2, true, true),
            MacroHotkey::Stop,
            "录制中按终止键 ⇒ 立即停止"
        );
        assert_eq!(
            PadApp::macro_hotkey_action(K2, 0, false, K2, true, false),
            MacroHotkey::None,
            "未处于录制状态时按终止键 = 无操作"
        );
        // ⑤ 两个都启用:开始键在录制中不该重复开(否则清掉刚录到的步骤)
        assert_eq!(
            PadApp::macro_hotkey_action(K1, K1, true, K2, true, true),
            MacroHotkey::None,
            "已在录制中再按开始键:不重开(保护已录步骤)"
        );
        assert_eq!(
            PadApp::macro_hotkey_action(K1, K1, true, K2, true, false),
            MacroHotkey::Start
        );
        assert_eq!(
            PadApp::macro_hotkey_action(K2, K1, true, K2, true, true),
            MacroHotkey::Stop
        );
        // ⑥ 两个都未启用 ⇒ 任何键都不产生行为(原有逻辑不变)
        for code in [K1, K2, OTHER] {
            assert_eq!(
                PadApp::macro_hotkey_action(code, K1, false, K2, false, false),
                MacroHotkey::None,
                "都未启用时按键 {code} 不得有任何行为"
            );
        }
        // ⑦ 无关按键永远不触发
        assert_eq!(
            PadApp::macro_hotkey_action(OTHER, K1, true, K2, true, true),
            MacroHotkey::None
        );
    }

    /// **宏录制热键**:两个热键都只认**按下**边沿,且热键事件本身不进录制。
    ///
    /// 任务书明确:"热键事件本身不应被写入宏录制内容""不应递归触发录制"。
    /// 这里锁住的是**接线位置**的语义:热键命中即 `continue`,不落到
    /// `record_macro_button`。若有人把热键判定挪到录制写入之后,这条会失败。
    #[test]
    fn macro_record_hotkey_events_never_enter_the_macro() {
        let mut rec = MacroRecording {
            steps: Vec::new(),
            held: HashSet::new(),
            last_event: Instant::now(),
            last_step_at: Instant::now(),
            idle_ms: 800,
        };
        // 普通键照常被记录
        PadApp::record_macro_button(&mut rec, 30, true, Instant::now());
        assert_eq!(rec.steps.len(), 1, "普通键必须被记录");

        // 热键在事件循环里是 `continue` 掉的 —— 等价于"不调用 record_macro_button"。
        // 这里用"判定为 Start/Stop 的键不喂给录制"来锁住同一语义。
        const K1: u16 = 88;
        const K2: u16 = 89;
        assert_ne!(
            PadApp::macro_hotkey_action(K1, K1, true, K2, true, false),
            MacroHotkey::None,
            "K1 是热键"
        );
        // 因为它被判为热键,调用方会 continue ⇒ 不会被喂进录制
        let before = rec.steps.len();
        // (模拟调用方:命中热键就不调 record)
        if PadApp::macro_hotkey_action(K1, K1, true, K2, true, false) == MacroHotkey::None {
            PadApp::record_macro_button(&mut rec, K1, true, Instant::now());
        }
        assert_eq!(
            rec.steps.len(),
            before,
            "热键不得被写入宏(任务书:热键事件本身不应写入录制内容)"
        );
    }
