#[test]
fn tests_never_touch_the_production_log_path() {
    let prod = crate::app::config_dir().join(FILE_NAME);
    init();
    let in_use = path();
    assert_ne!(
        in_use, prod,
        "测试构建下 init() 必须落到临时目录,不许指向生产日志 {}",
        prod.display()
