                egui::RichText::new(action.label())
                    .color(egui::Color32::WHITE)
                    .strong(),
            )
            .fill(th.danger)
            .stroke(egui::Stroke::new(1.0, egui::Color32::WHITE)),
        )
        .on_hover_text(action.tooltip());
    if r.clicked() {
        match action {
            RescueAction::ReconnectGaveUp | RescueAction::Reconnecting => {
                // 重新发起连接:清零退避计数,让自动重连重新武装
                self.reconnect_attempts = 0;
                self.reconnect_due = None;
                self.connect_control();
                self.log("已重新发起连接(右上角红色按钮)");
            }
            RescueAction::ChannelDead => {
                self.force_reconnect_control_channel();
            }
            RescueAction::MappingWithoutChannel => {
                self.connect_control();
                self.log("正在连接控制通道(右上角红色按钮)");
            }
        }
    }
}

