/// 右上角「重新连接」按钮(用户 2026-10-12)。
///
/// 取代上一版的"红色哑光占位块":用户实测那个占位块在点击连接后会闪一下,
/// 而且平时"一直在显示一些没用的东西"。按用户的"有始必有终"原则:
/// 去掉占位块,但**功能就地保留** —— 一个常驻、有字的「重新连接」按钮。
///
/// 为什么不再闪:按钮**本体常驻不变**(位置、大小、文字都固定),
/// 只有"要不要高亮"随状态变;不会出现"整块消失↔出现"的跳变。
fn reconnect_button(&mut self, ui: &mut egui::Ui, th: &theme::Theme) {
    let action = pick_rescue_action(&self.rescue_candidates());
    // 常驻:始终显示「重新连接」。需要时高亮(红),平时普通外观。
    let btn = if action.is_some() {
        egui::Button::new(egui::RichText::new("重新连接").color(egui::Color32::WHITE).strong())
            .fill(th.danger)
            .stroke(egui::Stroke::new(1.0, egui::Color32::WHITE))
    } else {
        egui::Button::new("重新连接")
    };
    let tip = action.map(|a| a.tooltip()).unwrap_or(
        "重新发起连接(清零退避计数)。\n已连接时点它 = 重连一次。",
    );
    if ui.add(btn).on_hover_text(tip).clicked() {
        // 动作与上一版一致(按仲裁结果走对应的那条路)
        match action {
            Some(RescueAction::ChannelDead) => self.force_reconnect_control_channel(),
            _ => {
                self.reconnect_attempts = 0;
                self.reconnect_due = None;
                self.connect_control();
                self.log("已重新发起连接(右上角[重新连接])");
            }
        }
    }
}
```

