        let action = pick_rescue_action(&self.rescue_candidates());
        // 固定宽度:按**最长**的标签预留,位置不跳(与旁边"取消X"槽位同一纪律)
        let font = egui::TextStyle::Button.resolve(ui.style());
        let widest = [
            RescueAction::ReconnectGaveUp,
            RescueAction::Reconnecting,
            RescueAction::ChannelDead,
            RescueAction::MappingWithoutChannel,
        ]
        .iter()
        .map(|a| {
            ui.painter()
                .layout_no_wrap(a.label().to_string(), font.clone(), egui::Color32::WHITE)
                .size()
                .x
        })
        .fold(0.0_f32, f32::max);
        let slot = egui::vec2(widest + 18.0, ui.spacing().interact_size.y);
        let (rect, _) = ui.allocate_exact_size(slot, egui::Sense::hover());
        let Some(action) = action else {
            // 一切正常:哑光无字的占位块(不响应点击,避免误触)
            let painter = ui.painter();
            painter.rect_filled(rect, 3.0, th.danger.gamma_multiply(0.10));
            painter.rect_stroke(
                rect,
                3.0,
                egui::Stroke::new(1.0, theme::with_alpha(th.danger, 60)),
                egui::StrokeKind::Inside,
            );
            return;
        };
        // 需要时:亮起来(实心红 + 文字),并且**一直亮**
        let r = ui
            .put(
                rect,
                egui::Button::new(
                    egui::RichText::new(action.label())
                        .color(egui::Color32::WHITE)
                        .strong(),
                )
                .fill(th.danger)
                .stroke(egui::Stroke::new(1.0, egui::Color32::WHITE)),
            )
            .on_hover_text(action.tooltip());
        if r.clicked() {
            match action {
                RescueAction::ReconnectGaveUp | RescueAction::Reconnecting => {
                    // 重新发起连接:清零退避计数,让自动重连重新武装
                    self.reconnect_attempts = 0;
                    self.reconnect_due = None;
                    self.connect_control();
                    self.log("已重新发起连接(右上角红色按钮)");
                }
                RescueAction::ChannelDead => {
                    self.force_reconnect_control_channel();
                }
                RescueAction::MappingWithoutChannel => {
                    self.connect_control();
                    self.log("正在连接控制通道(右上角红色按钮)");
                }
            }
        }
    }

