/// 只有"要不要高亮"随状态变;不会出现"整块消失↔出现"的跳变。
fn reconnect_button(&mut self, ui: &mut egui::Ui, th: &theme::Theme) {
    let action = pick_rescue_action(&self.rescue_candidates());
