}

/// 找出属于 `pid` 的**主窗口**在屏幕上的矩形(物理像素)。
///
/// 用途:遮板要贴在投屏窗口上,就必须知道它在哪。判据(按可靠性排序):
/// 1. 该 pid 的**可见、非最小化、有标题**的顶层窗口里,**面积最大**的那个 ——
///    投屏窗口就是它;排除工具窗(`WS_EX_TOOLWINDOW`)与我们自己的窗口。
/// 2. 找不到 ⇒ `None`(调用方据此**退回隔膜**,而不是凭空贴一块遮板)。
///
/// 为什么用"面积最大"而不是"第一个":一个进程可能同时有隐藏窗、消息窗、
/// 输入法窗等若干顶层窗,枚举顺序不保证;投屏窗口是其中最大的可见窗。
///
/// 这是**只读**查询,不改动任何窗口。
pub fn window_rect_of_pid(pid: u32) -> Option<MaskRect> {
    if pid == 0 {
        return None;
    }
    unsafe {
        let mut best: Option<MaskRect> = None;
        let mut best_area: i64 = 0;
        let mut ctx = FindCtx {
            pid,
            best: &mut best,
            best_area: &mut best_area,
        };
        EnumWindows(Some(enum_collect_pid), &mut ctx as *mut FindCtx as LPARAM);
        best
    }
}

/// `EnumWindows` 回调的上下文(回调是 C ABI 自由函数,状态只能这样传)。
struct FindCtx {
    pid: u32,
    best: &'static mut Option<MaskRect>,
    best_area: &'static mut i64,
}

unsafe extern "system" fn enum_collect_pid(hwnd: HWND, lparam: LPARAM) -> i32 {
    let ctx = unsafe { &mut *(lparam as *mut FindCtx) };
    unsafe {
        if IsWindowVisible(hwnd) == 0 || IsIconic(hwnd) != 0 {
            return 1; // 继续枚举
        }
        // 排除工具窗(输入法/托盘之类)与无标题窗
        let ex = GetWindowLongW(hwnd, GWL_EXSTYLE) as u32;
        if ex & WS_EX_TOOLWINDOW != 0 {
            return 1;
        }
        let mut pid = 0u32;
        GetWindowThreadProcessId(hwnd, &mut pid);
        if pid != ctx.pid {
            return 1;
        }
        let mut r = RECT {
            left: 0,
            top: 0,
            right: 0,
            bottom: 0,
        };
        if GetWindowRect(hwnd, &mut r) == 0 {
            return 1;
        }
        let w = r.right - r.left;
        let h = r.bottom - r.top;
        if w < 32 || h < 32 {
            return 1; // 太小:不是投屏窗口
        }
        let area = i64::from(w) * i64::from(h);
        if area > *ctx.best_area {
            *ctx.best_area = area;
            *ctx.best = Some(MaskRect::new(r.left, r.top, w, h));
        }
        1 // 继续枚举完(要比较面积)
    }
}

