{"file_path": "D:\GitHub\scrcpy-pad-developing-yaml\src\app.rs", "new_string": "    /// 遮板(窗口层接管鼠标)的**热切换 + 每帧同步**(用户 2026-10-13)。
    ///
    /// 语义(与隔膜的关系):
    /// - 外观页选「遮板」⇒ 起一块透明置顶窗贴在投屏窗口上,鼠标事件落在它身上,
    ///   底下的投屏窗口收不到 ⇒ 双份输入从根上消失;**同时把钩子层隔膜关掉**
    ///   (两者同时生效会把鼠标吞两次,而且界面也点不了)。
    /// - 外观页选「隔膜」(默认)⇒ 立刻销毁遮板,回到从前那条路。
    /// - **热切换**:翻转后下一帧就走完上面两条,不必重启。
    ///
    /// 三条**自动退回**条件(起不来就不硬撑,回到隔膜):
    /// ① 非 Windows(`available()` 为 false);
    /// ② 定位不到投屏窗口矩形(还没启动投屏 / 窗口最小化);
    /// ③ 创建窗口失败(权限/资源)。
    /// 退回时写一条日志(**只在状态变化时**写一次,不刷屏)。
    ///
    /// 参数 `shield_wanted` = 隔膜那套判据算出来的结果;本函数在遮板模式下会
    /// 把它**覆盖成 false**(见上:两者只能有一个生效)。
    fn sync_mouse_capture(&mut self, shield_wanted: bool) -> bool {
        let mode = self.look().mouse_capture;
        let want_mask = mode == theme::MouseCaptureMode::Mask && crate::mask::available();
        if !want_mask {
            // 隔膜模式(或平台不支持):确保遮板已收掉
            if self.mask.take().is_some() {
                self.mask_rect = None;
                self.mask_rect_at = None;
                crate::diag_info!("app", "鼠标接管:已切回隔膜(遮板窗口已销毁)");
            }
            return shield_wanted;
        }
        // ---- 遮板模式 ----
        // 只在需要时(重新)定位投屏窗口:节流 500ms,或还没定过位。
        const RELOCATE_MS: u128 = 500;
        let due = self
            .mask_rect_at
            .is_none_or(|t| t.elapsed().as_millis() >= RELOCATE_MS);
        if due {
            self.mask_rect_at = Some(std::time::Instant::now());
            let pid = self.scrcpy_pid;
            let found = pid.and_then(crate::mask::window_rect_of_pid);
            match (found, self.mask.is_some()) {
                (Some(r), _) => self.mask_rect = Some(r),
                (None, true) => {
                    // 投屏窗口没了(用户关了投屏):收掉遮板,退回隔膜
                    self.mask = None;
                    self.mask_rect = None;
                    self.log("遮板:定位不到投屏窗口,已退回隔膜");
                }
                (None, false) => {}
            }
        }
        let Some(rect) = self.mask_rect else {
            // 还没定位到:本帧退回隔膜(不能凭空贴一块遮板挡住整个屏幕)
            return shield_wanted;
        };
        // 起窗(只起一次)
        if self.mask.is_none() {
            match crate::mask::Mask::start(rect) {
                Ok(m) => {
                    self.mask = Some(m);
                    self.log(format!(
                        "遮板已启用:贴在投屏窗口 ({},{}) {}x{};鼠标事件由它接管(隔膜已让位)",
                        rect.x, rect.y, rect.w, rect.h
                    ));
                }
                Err(e) => {
                    self.log(format!("遮板起窗失败({e}),已退回隔膜"));
                    return shield_wanted;
                }
            }
        }
        // 提交本帧内容:矩形(跟随投屏窗口移动/缩放)+ 键位/轮盘/锚点图形。
        // `passthrough = false` = **吃掉**鼠标事件(这正是遮板存在的意义)。
        if let Some(m) = self.mask.as_ref() {
            let mut frame = crate::mask::Frame::new(rect);
            frame.passthrough = false;
            self.fill_mask_shapes(&mut frame);
            m.set_frame(frame);
        }
        // 遮板生效期间**隔膜必须关掉**:两套一起上会把鼠标吞两次。
        false
    }

    /// 往遮板那一帧里塞要画的图形(键位圈 / 轮盘圈 / 瞄准锚点)。
    ///
    /// 坐标换算:键位配置里存的是**设备触摸坐标空间**,而遮板用的是**屏幕像素** ——
    /// 两者按投屏窗口的矩形等比缩放。这样画出来的圈正好落在游戏里对应的位置上。
    fn fill_mask_shapes(&self, frame: &mut crate::mask::Frame) {
        let (sw, sh, screen) = {
            let g = lock_shared(&self.shared);
            let screen = g
                .control
                .as_ref()
                .map(|c| (c.screen_w, c.screen_h))
                .or(g.profile.screen)
                .unwrap_or((0, 0));
            (g.profile.screen.0, g.profile.screen.1, screen)
        };
        let _ = (sw, sh);
        let (dw, dh) = screen;
        if dw == 0 || dh == 0 || frame.rect.w <= 0 || frame.rect.h <= 0 {
            return;
        }
        let sx = frame.rect.w as f32 / dw as f32;
        let sy = frame.rect.h as f32 / dh as f32;
        let to_screen = |x: i32, y: i32| -> (i32, i32) {
            (
                frame.rect.x + (x as f32 * sx) as i32,
                frame.rect.y + (y as f32 * sy) as i32,
            )
        };
        let g = lock_shared(&self.shared);
        // 键位(只画"响应范围圈",不画整张虚拟键盘 —— 那会盖住游戏画面)
        for b in &g.profile.binds {
            let (cx, cy) = b.center;
            let (px, py) = to_screen(cx, cy);
            let r = ((b.radius.max(8) as f32) * sx.max(sy)) as i32;
            let kind = if b.fps_only {
                crate::mask::ShapeKind::Fps
            } else {
                crate::mask::ShapeKind::Bind
            };
            frame.shapes.push(crate::mask::Shape::new(
                kind,
                px,
                py,
                r,
                crate::keymap::key_name(b.key),
            ));
        }
        // 轮盘(圆心 + 半径)
        for w in &g.profile.wheels {
            let (px, py) = to_screen(w.center.0, w.center.1);
            let r = ((w.radius.max(8) as f32) * sx.max(sy)) as i32;
            frame
                .shapes
                .push(crate::mask::Shape::new(crate::mask::ShapeKind::Wheel, px, py, r, ""));
        }
        // 瞄准锚点(画成小十字/小圈,便于对位)
        if g.profile.aim.enabled && g.profile.aim.anchor_set() {
            let (px, py) = to_screen(g.profile.aim.anchor_x_px(dw), g.profile.aim.anchor_y_px(dh));
            frame.shapes.push(crate::mask::Shape::new(
                crate::mask::ShapeKind::Aim,
                px,
                py,
                10,
                "",
            ));
        }
    }

    /// S③:「鼠标独占」当前是否开启 + 原因文案(左栏状态行与瞄准面板**共用一处口径**)。", "old_string": "    /// S③:「鼠标独占」当前是否开启 + 原因文案(左栏状态行与瞄准面板**共用一处口径**)。"}

