    #[test]
    fn casing_and_plate_are_opposite_to_ink() {
        let light_ink = Color32::WHITE;
        let dark_ink = Color32::from_rgb(16, 16, 16);
        // 亮本体 -> 暗外套 / 暗衬底
        assert!(luma(casing(light_ink)) < 80.0);
