        // 暗本体 -> 亮外套 / 亮衬底
        assert!(luma(casing(dark_ink)) > 200.0);
        assert!(luma(plate(dark_ink)) > 200.0);
        // 衬底必须是半透明的(不能把截图糊死)
        assert!(plate(light_ink).a() < 255 && plate(dark_ink).a() < 255);
        assert!(casing(light_ink).a() < 255 && casing(dark_ink).a() < 255);
    }
