{"content": "// 只读探测:遮板能否定位到投屏窗口(scrcpy.exe)的矩形?
// 形态与生产代码逐字相同:EnumWindows + IsWindowVisible + IsIconic + GWL_EXSTYLE
// + GetWindowThreadProcessId + GetWindowRect,选"面积最大的可见非工具顶层窗"。
// 不改动任何窗口、不碰鼠标、不占单实例锁。
#![allow(non_snake_case, non_camel_case_types)]

use std::ffi::c_void;

type HWND = *mut c_void;
type LPARAM = isize;
type BOOL = i32;

#[repr(C)]
struct RECT { left: i32, top: i32, right: i32, bottom: i32 }

const GWL_EXSTYLE: i32 = -20;
const WS_EX_TOOLWINDOW: u32 = 0x00000080;

#[link(name = "user32")]
unsafe extern "system" {
    fn EnumWindows(lpEnumFunc: Option<unsafe extern "system" fn(HWND, LPARAM) -> BOOL>, lParam: LPARAM) -> BOOL;
    fn IsWindowVisible(hWnd: HWND) -> BOOL;
    fn IsIconic(hWnd: HWND) -> BOOL;
    fn GetWindowLongW(hWnd: HWND, nIndex: i32) -> i32;
    fn GetWindowThreadProcessId(hWnd: HWND, lpdwProcessId: *mut u32) -> u32;
    fn GetWindowRect(hWnd: HWND, lpRect: *mut RECT) -> BOOL;
    fn GetWindowTextW(hWnd: HWND, lpString: *mut u16, nMaxCount: i32) -> i32;
    fn GetClassNameW(hWnd: HWND, lpClassName: *mut u16, nMaxCount: i32) -> i32;
}

struct Ctx { pid: u32, best: Option<(i32,i32,i32,i32)>, area: i64, count: u32, found: Vec<String> }

unsafe extern "system" fn cb(hwnd: HWND, lparam: LPARAM) -> BOOL {
    let ctx = unsafe { &mut *(lparam as *mut Ctx) };
    unsafe {
        if IsWindowVisible(hwnd) == 0 || IsIconic(hwnd) != 0 { return 1; }
        let ex = GetWindowLongW(hwnd, GWL_EXSTYLE) as u32;
        if ex & WS_EX_TOOLWINDOW != 0 { return 1; }
        let mut pid = 0u32;
        GetWindowThreadProcessId(hwnd, &mut pid);
        if pid != ctx.pid { return 1; }
        let mut r = RECT { left:0, top:0, right:0, bottom:0 };
        if GetWindowRect(hwnd, &mut r) == 0 { return 1; }
        let (w, h) = (r.right - r.left, r.bottom - r.top);
        if w < 32 || h < 32 { return 1; }
        let mut title = [0u16; 256];
        let n = GetWindowTextW(hwnd, title.as_mut_ptr(), 256);
        let t = String::from_utf16_lossy(&title[..n.max(0) as usize]);
        let mut cls = [0u16; 256];
        let cn = GetClassNameW(hwnd, cls.as_mut_ptr(), 256);
        let c = String::from_utf16_lossy(&cls[..cn.max(0) as usize]);
        ctx.count += 1;
        ctx.found.push(format!("    hwnd={:p} ({},{}) {}x{} title={:?} class={:?}", hwnd, r.left, r.top, w, h, t, c));
        let area = i64::from(w) * i64::from(h);
        if area > ctx.area { ctx.area = area; ctx.best = Some((r.left, r.top, w, h)); }
        1
    }
}

fn find_rect(pid: u32) -> (Option<(i32,i32,i32,i32)>, Vec<String>) {
    unsafe {
        let mut ctx = Ctx { pid, best: None, area: 0, count: 0, found: Vec::new() };
        EnumWindows(Some(cb), &mut ctx as *mut Ctx as LPARAM);
        (ctx.best, ctx.found)
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let pid: u32 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(0);
    if pid == 0 {
        println!("用法: probe_mask <pid>");
        return;
    }
    println!("探测 pid={pid} 的顶层窗口(生产同形规则)…");
    let (best, all) = find_rect(pid);
    println!("  可见且非最小的顶层窗(排除工具窗/小窗):{} 个", all.len());
    for l in &all { println!("{l}"); }
    match best {
        Some((x, y, w, h)) => {
            println!("=> 选中(面积最大):({x},{y}) {w}x{h}");
            println!("ROOT=OK 遮板可以定位到投屏窗口");
        }
        None => println!("ROOT=NONE 定位不到(遮板会退回隔膜)"),
    }
}
