#![allow(non_snake_case, non_camel_case_types)]
use std::ffi::c_void;
type HWND=*mut c_void; type HINSTANCE=*mut c_void; type WPARAM=usize; type LPARAM=isize; type LRESULT=isize;
const WS_OVERLAPPEDWINDOW: u32 = 0x00CF0000; const CW_USEDEFAULT: i32 = -2147483648i32;
#[repr(C)] struct WNDCLASSW { style:u32, lpfnWndProc:Option<unsafe extern "system" fn(HWND,u32,WPARAM,LPARAM)->LRESULT>, cbClsExtra:i32, cbWndExtra:i32, hInstance:HINSTANCE, hIcon:HINSTANCE, hCursor:HINSTANCE, hbrBackground:HINSTANCE, lpszMenuName:*const u16, lpszClassName:*const u16 }
#[repr(C)] struct MSG { hwnd:HWND, message:u32, wParam:WPARAM, lParam:LPARAM, time:u32, pt_x:i32, pt_y:i32 }
#[link(name="user32")]
unsafe extern "system" {
    fn RegisterClassW(c:*const WNDCLASSW)->u16;
    fn CreateWindowExW(ex:u32,cls:*const u16,title:*const u16,style:u32,x:i32,y:i32,w:i32,h:i32,parent:HWND,menu:HINSTANCE,inst:HINSTANCE,param:*const c_void)->HWND;
    fn ShowWindow(h:HWND,cmd:i32)->i32;
    fn GetMessageW(m:*mut MSG,h:HWND,min:u32,max:u32)->i32;
    fn TranslateMessage(m:*const MSG)->i32;
    fn DispatchMessageW(m:*const MSG)->LRESULT;
    fn DefWindowProcW(h:HWND,m:u32,w:WPARAM,l:LPARAM)->LRESULT;
    fn GetCurrentProcessId()->u32;
}
unsafe extern "system" fn wp(h:HWND,m:u32,w:WPARAM,l:LPARAM)->LRESULT{ unsafe{DefWindowProcW(h,m,w,l)} }
fn main(){
    unsafe{
        let cls:Vec<u16>="probe_win\0".encode_utf16().collect();
        let wc=WNDCLASSW{style:0,lpfnWndProc:Some(wp),cbClsExtra:0,cbWndExtra:0,hInstance:std::ptr::null_mut(),hIcon:std::ptr::null_mut(),hCursor:std::ptr::null_mut(),hbrBackground:std::ptr::null_mut(),lpszMenuName:std::ptr::null(),lpszClassName:cls.as_ptr()};
        RegisterClassW(&wc);
        let t:Vec<u16>="probe target\0".encode_utf16().collect();
        let h=CreateWindowExW(0,cls.as_ptr(),t.as_ptr(),WS_OVERLAPPEDWINDOW,300,200,640,480,std::ptr::null_mut(),std::ptr::null_mut(),std::ptr::null_mut(),std::ptr::null());
        if h.is_null(){println!("CREATE_FAIL");return;}
        ShowWindow(h,5); // SW_SHOW
        println!("PID={}", GetCurrentProcessId());
        println!("窗口已显示 (300,200) 640x480,5 秒后自动关闭");
        std::thread::spawn(||{ std::thread::sleep(std::time::Duration::from_secs(5)); std::process::exit(0); });
        let mut m:MSG=std::mem::zeroed();
        while GetMessageW(&mut m,std::ptr::null_mut(),0,0)>0 { TranslateMessage(&m); DispatchMessageW(&m); }
    }
}
EOF
