#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct OverlayFilter {
    keys: bool,
    combos: bool,
    macros: bool,
    wheels_perm: bool,
    wheels_temp: bool,
    aim: bool,
}

/// 遮板(蒙版)显示项目的位标志(用户 2026-10-13 第 2 条)。
