{"file_path": "D:\GitHub\scrcpy-pad-developing-yaml\src\app.rs", "new_string": "/// 宏绑定在遮板上的"中心点"(相对坐标)。
///
/// 宏没有"响应范围圆"(它的动作是一串步骤),所以取它**第一条录制步骤**涉及的
/// 普通绑定中心,或者干脆不画 —— 这里返回 `None` 表示"这条宏没有可画的位置",
/// 由调用方跳过。加这个辅助函数是为了让 `fill_mask_shapes` 里的过滤判断
/// 保持一行,不必在那里展开宏的内部结构。
fn macro_bind_center(action: &Action) -> Option<(f32, f32)> {
    let Action::Macro(m) = action else {
        return None;
    };
    // 宏的录制步骤是原始按键事件,没有坐标;只有"设置步骤"里的 Tap/Hold 有位置。
    for ins in &m.instructions {
        match ins {
            MacroInstruction::Key { .. } => {}
            MacroInstruction::Tap { x, y, .. } | MacroInstruction::Hold { x, y, .. } => {
                return Some((*x, *y));
            }
            _ => {}
        }
    }
    None
}

