// 用户指定:入口在「外观」,两项二选,**支持热切换**。
// 两者解决同一个问题(同一次点击被投递两份:投屏程序一份、我们的映射一份),
// 区别只在**在哪一层拦**:隔膜在钩子层吞消息,遮板在窗口层贴一块透明窗。
//
// 注意:它存在 `settings.json`(**程序级**),不是 `Look` 的一部分 ——
// 放 Look 里会跟着按键组合走、还会被 look.json 覆盖,实测导致
// "选了遮板却跑成隔膜"。界面入口仍按用户要求留在这里。
ui.separator();
ui.horizontal(|ui| {
    ui.label("鼠标接管:");
    egui::ComboBox::from_id_salt("look_mouse_capture")
        .selected_text(self.mouse_capture.label())
        .show_ui(ui, |ui| {
            for m in theme::MouseCaptureMode::ALL {
                if ui
                    .selectable_value(&mut self.mouse_capture, m, m.label())
                    .on_hover_text(m.hint())
                    .changed()
                {
                    // 程序级设置:立刻登记落盘(下一帧 `sync_mouse_capture`
                    // 就会起窗/销毁,不需要重启任何东西)。
                    self.remember_now();
                    crate::diag_warn!(
                        "app",
                        "鼠标接管方式切换为 {} (热切换,下一帧生效)",
                        m.label()
                    );
                }
            }
        });
    // 第 2 条:选了遮板时,右侧给一个"显示项目"下拉 ——
    // 项目与「截图取点」**逐项相同**(同一个 `OverlayFilter`)。
    if self.mouse_capture == theme::MouseCaptureMode::Mask {
        ui.label("显示项目:");
        let before = self.mask_filter;
        self.mask_filter.ui(ui);
        if self.mask_filter != before {
            self.remember_now();
        }
        if !crate::mask::available() {
            ui.colored_label(
                egui::Color32::from_rgb(230, 160, 60),
                "本平台不支持遮板,将退回隔膜",
            );
        }
    }
});
