// 只读探测:Windows CompareStringEx 在 zh-CN 下是否按**拼音**排序中文?
#![allow(non_snake_case)]
type BOOL = i32;
#[link(name="kernel32")]
unsafe extern "system" {
    fn CompareStringEx(
        lpLocaleName: *const u16, dwCmpFlags: u32,
        lpString1: *const u16, cchCount1: i32,
        lpString2: *const u16, cchCount2: i32,
        lpVersionInformation: *const core::ffi::c_void,
        lpReserved: *const core::ffi::c_void, lParam: isize,
    ) -> i32;
    fn LCMapStringEx(
        lpLocaleName: *const u16, dwMapFlags: u32,
        lpSrcStr: *const u16, cchSrc: i32,
        lpDestStr: *mut u16, cchDest: i32,
        lpVersionInformation: *const core::ffi::c_void,
        lpReserved: *const core::ffi::c_void, lParam: isize,
    ) -> i32;
}
fn wide(s:&str)->Vec<u16>{ s.encode_utf16().chain(std::iter::once(0)).collect() }
fn main(){
    let locale = wide("zh-CN");
    // 一组中文:按拼音应为 安(a) 白(b) 才(c) 大(d) 而(e)
    // 若按 Unicode 码点排则是 一(y) 丁(d) 万(w) 上(s) 不(b) —— 顺序完全不同
    let words = ["一","丁","万","上","不"];
    println!("原始顺序(Unicode 码点序): {:?}", words);
    unsafe {
        let mut v: Vec<&str> = words.to_vec();
        v.sort_by(|a,b|{
            let (wa,wb)=(wide(a),wide(b));
            let r = CompareStringEx(locale.as_ptr(), 0, wa.as_ptr(), -1, wb.as_ptr(), -1,
                std::ptr::null(), std::ptr::null(), 0);
            r - 2  // CSTR_LESS_THAN=1 ⇒ -1
        });
        println!("CompareStringEx(zh-CN) 排序: {:?}", v);
        let pinyin_expected = ["不","丁","上","万","一"]; // b, d, s, w, y
        println!("按拼音应为:              {:?}", pinyin_expected);
        println!("=> {}", if v == pinyin_expected { "PINYIN_OK 确实是拼音序" } else { "NOT_PINYIN 不是拼音序" });
        // 再看 LCMapStringEx 能否直接给出拼音(用于生成排序键)
        let mut dest = [0u16; 256];
        let n = LCMapStringEx(locale.as_ptr(), 0x00040000 /*SORT_STRINGSORT? 用 0 试*/,
            wide("三角洲行动").as_ptr(), -1, dest.as_mut_ptr(), 256,
            std::ptr::null(), std::ptr::null(), 0);
        if n > 0 {
            println!("LCMapStringEx 结果: {:?}", String::from_utf16_lossy(&dest[..(n as usize).saturating_sub(1)]));
        }
    }
}
EOF
