        //
        // **坐标系约定(修"图形缩到窗口外/偏左上角"的根因)**:
        // 蒙版窗口的绘制是 GDI 的 `Ellipse`/`FillRect`,它们吃的是**窗口客户区
        // 坐标**(左上角 = 0,0),**不是屏幕坐标**。而画面区域又要靠"投屏窗口的
        // 客户区在屏幕上的位置"来定位 —— 所以这里必须做**两次减法**:
        //   屏幕坐标 = 投屏窗口客户区原点 + 画面在客户区内的偏移 + 设备像素×scale
        //   窗口坐标 = 屏幕坐标 - **蒙版窗口自己**的客户区原点
        // 上一版把"屏幕坐标"直接当成窗口坐标交给 GDI,于是图形整体偏移了一个
        // (`client_x`, `client_y`) —— 窗口越大偏得越离谱(用户实测:"普通缩放
        // 根本无法显示蒙版,蒙版都缩到窗口外面了")。
        //
        // 蒙版窗口自身的矩形就是 `frame.rect`(它贴在投屏窗口上),所以它自己的
        // 客户区原点≈`frame.rect` 左上角(无边框的 popup 窗口,客户区=整窗)。
        let (win_w, win_h) = (frame.rect.w as f32, frame.rect.h as f32);
        // 画面比例 = 手机长宽比(设备触摸空间),横竖屏各自正确
        let scale = (win_w / dw).min(win_h / dh);
        let view_w = dw * scale;
        let view_h = dh * scale;
        let off_x = (win_w - view_w) / 2.0;
        let off_y = (win_h - view_h) / 2.0;
        // 设备像素 → **蒙版窗口客户区坐标**(已经是窗口内坐标,不含任何屏幕原点)
        let to_screen = |x: i32, y: i32| -> (i32, i32) {
            (
                (off_x + x as f32 * scale) as i32,
                (off_y + y as f32 * scale) as i32,
            )
        };", "old_string": "        let (win_w, win_h) = (frame.rect.w as f32, frame.rect.h as f32);
        // 客户区尺寸(不含标题栏/边框);拿不到时退回窗口矩形
        let (client_w, client_h, client_x, client_y) = match crate::mask::client_area_of_pid(
            self.scrcpy_pid.unwrap_or(0),
        ) {
            Some((cx, cy, cw, ch)) => (cw as f32, ch as f32, cx as f32, cy as f32),
            None => (win_w, win_h, frame.rect.x as f32, frame.rect.y as f32),
        };
        let scale = (client_w / dw).min(client_h / dh);
        // 画面在客户区内的实际显示尺寸与居中偏移
        let view_w = dw * scale;
        let view_h = dh * scale;
        let off_x = (client_w - view_w) / 2.0;
        let off_y = (client_h - view_h) / 2.0;
        let to_screen = |x: i32, y: i32| -> (i32, i32) {
            (
                (client_x + off_x + x as f32 * scale) as i32,
                (client_y + off_y + y as f32 * scale) as i32,"}

