#![allow(non_snake_case, non_camel_case_types)]
use std::ffi::c_void;
type HWND=*mut c_void; type LPARAM=isize; type BOOL=i32;
#[repr(C)] struct RECT{left:i32,top:i32,right:i32,bottom:i32}
#[repr(C)] struct POINT{x:i32,y:i32}
const GWL_EXSTYLE:i32=-20; const WS_EX_TOOLWINDOW:u32=0x80;
#[link(name="user32")]
unsafe extern "system" {
    fn EnumWindows(f:Option<unsafe extern "system" fn(HWND,LPARAM)->BOOL>,l:LPARAM)->BOOL;
    fn IsWindowVisible(h:HWND)->BOOL; fn IsIconic(h:HWND)->BOOL;
    fn GetWindowLongW(h:HWND,i:i32)->i32;
    fn GetWindowThreadProcessId(h:HWND,p:*mut u32)->u32;
    fn GetWindowRect(h:HWND,r:*mut RECT)->BOOL;
    fn GetClientRect(h:HWND,r:*mut RECT)->BOOL;
    fn ClientToScreen(h:HWND,p:*mut POINT)->BOOL;
    fn GetWindowTextW(h:HWND,s:*mut u16,n:i32)->i32;
}
struct Ctx{pid:u32,best:*mut Option<(HWND,i64)>}
unsafe extern "system" fn cb(hwnd:HWND,lparam:LPARAM)->BOOL{
    let ctx=unsafe{&mut *(lparam as *mut Ctx)};
    unsafe{
        if IsWindowVisible(hwnd)==0||IsIconic(hwnd)!=0{return 1;}
        if GetWindowLongW(hwnd,GWL_EXSTYLE) as u32 & WS_EX_TOOLWINDOW != 0 {return 1;}
        let mut pid=0u32; GetWindowThreadProcessId(hwnd,&mut pid);
        if pid!=ctx.pid{return 1;}
        let mut cr=RECT{left:0,top:0,right:0,bottom:0};
        if GetClientRect(hwnd,&mut cr)==0{return 1;}
        let (w,h)=(cr.right-cr.left,cr.bottom-cr.top);
        if w<32||h<32{return 1;}
        let area=i64::from(w)*i64::from(h);
        let better=match *ctx.best{Some((_,a))=>area>a,None=>true};
        if better{*ctx.best=Some((hwnd,area));}
        1
    }
}
fn main(){
    let pid:u32=std::env::args().nth(1).and_then(|s|s.parse().ok()).unwrap_or(0);
    let space:(f32,f32)=(std::env::args().nth(2).and_then(|s|s.parse().ok()).unwrap_or(2772.0),
                         std::env::args().nth(3).and_then(|s|s.parse().ok()).unwrap_or(1280.0));
    unsafe{
        let mut found:Option<(HWND,i64)>=None;
        let mut ctx=Ctx{pid,best:&mut found as *mut Option<(HWND,i64)>};
        EnumWindows(Some(cb), &mut ctx as *mut Ctx as LPARAM);
        let Some((hwnd,_))=found else {println!("找不到可见窗口(pid={pid})");return;};
        let mut wr=RECT{left:0,top:0,right:0,bottom:0}; GetWindowRect(hwnd,&mut wr);
        let mut cr=RECT{left:0,top:0,right:0,bottom:0}; GetClientRect(hwnd,&mut cr);
        let mut o=POINT{x:0,y:0}; ClientToScreen(hwnd,&mut o);
        let mut t=[0u16;256]; let n=GetWindowTextW(hwnd,t.as_mut_ptr(),256);
        println!("窗口标题: {:?}", String::from_utf16_lossy(&t[..n.max(0) as usize]));
        println!("整窗(GetWindowRect):   ({},{}) {}x{}", wr.left,wr.top,wr.right-wr.left,wr.bottom-wr.top);
        println!("客户区(屏幕坐标):      ({},{}) {}x{}", o.x,o.y,cr.right-cr.left,cr.bottom-cr.top);
        let (cw,ch)=((cr.right-cr.left) as f32,(cr.bottom-cr.top) as f32);
        let (dw,dh)=space;
        let scale=(cw/dw).min(ch/dh);
        let (vw,vh)=((dw*scale).round() as i32,(dh*scale).round() as i32);
        let ox=o.x+((cw as i32)-vw)/2; let oy=o.y+((ch as i32)-vh)/2;
        println!("--- 按手机比例 {dw}x{dh} 算出的**画面矩形**(新方案贴这个) ---");
        println!("  原点=({ox},{oy}) 尺寸={vw}x{vh}  (scale={scale:.5})");
        println!("  宽高比={:.5}  手机宽高比={:.5}", vw as f32/vh as f32, dw/dh);
        let lg=(ox-o.x) as f32; let rg=((o.x+cw as i32)-(ox+vw)) as f32;
        let tg=(oy-o.y) as f32; let bg=((o.y+ch as i32)-(oy+vh)) as f32;
        println!("  黑边: 左{lg:.0} 右{rg:.0} 上{tg:.0} 下{bg:.0}");
    }
}
