enum SchedAct {
    Up {
        pid: u64,
        x: i32,
        y: i32,
        lane: BindLane,
    },
    Move {
        pid: u64,
        x: i32,
        y: i32,
    },
    /// 宏：直接注入 Android 系统键。
    MacroAndroidKey {
        keycode: u32,
        down: bool,
    },
    /// 设置宏：切换 FPS 模式。
    MacroFps {
        on: bool,
    },
    /// 设置宏：临时按下/释放轮盘方向（作用于**当前配置**的活轮盘；
    /// 虚拟层的轮盘方向在排程期就展开成自包含的滑动手势，不走这里）。
    MacroWheel {
        wheel: usize,
        part: MacroWheelPart,
        down: bool,
    },
    /// 宏触点：在相对坐标处按下/抬起。抬起只对运行表（`macro_down`）里
    /// 记着的 pid 生效——排程与执行两端共同保证"没有只按不抬"。
    MacroClick {
        pid: u64,
        x: f32,
        y: f32,
        down: bool,
    },
    /// 宏触点：把手指移动到相对坐标（滑动轨迹使用）。
    MacroMove {
        pid: u64,
        x: f32,
        y: f32,
    },
    /// 执行轮盘的终点抬起。
    WheelUp {
        wheel: usize,
        x: i32,
        y: i32,
    },
    /// 「按后延迟」到期后重放一次被推迟的按下(用户 2026-10-10 第 2 条)。
    /// `code` 是行这一动作的物理键码 —— 重放前核对一下,防止期间配置被改过、
    /// 同一个下标已经换成了另一条键位(那就别把新键位按下去)。
    Redispatch {
        idx: usize,
        lane: BindLane,
        code: u16,
    },

