                        // 取 64 击(约 64×间隔)—— 远超人手按住时长能触发的数量,
                        // 且保证这个向量有界(不会因为一次按键就撑爆内存)。
                        const MAX_REPEAT_BURST: u64 = 64;
                        let mut t = up_at;
                        for _ in 0..MAX_REPEAT_BURST {
                            t += Duration::from_millis(interval);
                            scheduled.push((
