        assert!(st.downs >= 1, "轨迹滑动必须落指");
        assert_eq!(st.downs, st.ups, "轨迹滑动收尾必须抬指(无泄漏)");
        assert!(st.moves >= 2, "轨迹必须产生多次移动(实测 {})", st.moves);
        // 关键:轨迹**折返**过 ⇒ 设备端 x 坐标应同时出现"左半"和"右半"。
