{"command": "cd D:/GitHub/scrcpy-pad-developing-yaml
OUT=release/windows-x86_64
cp target/release/scrcpy-pad.exe "$OUT/scrcpy-pad.exe"
python - <<'PY'
import hashlib, os, zipfile
out='release/windows-x86_64'; zp='release/scrcpy-pad-0.2.0-windows-x86_64.zip'
if os.path.exists(zp): os.remove(zp)
with zipfile.ZipFile(zp,'w',zipfile.ZIP_DEFLATED) as z:
    for root,dirs,files in os.walk(out):
        for f in sorted(files):
            if '.inuse-' in f: continue
            p=os.path.join(root,f); z.write(p, os.path.relpath(p, os.path.dirname(out)).replace(os.sep,'/'))
def md5(p):
    h=hashlib.md5()
    with open(p,'rb') as fh:
        for b in iter(lambda: fh.read(1<<20), b''): h.update(b)
    return h.hexdigest()
for p in [out+'/scrcpy-pad.exe', zp]: print(f"{md5(p)}  {os.path.getsize(p):>10}  {p}")
PY
echo "=== 清理 ==="; ls *.rs *.tmp *.exe 2>/dev/null | grep -v "^src/" || echo "(无临时文件)"
tasklist 2>/dev/null | grep -ciE "cargo|rustc|probe" || echo "0 残留"", "timeoutMs": 600000}

